insert into public.questions (id, subject_id, grade, difficulty, standard, skill, prompt, choices, answer_index, explanation, xp, kind) values
('54460457-d1be-4bd8-a36f-7f4f66c65667', 'reading', 'K', 1, 'ELA.K.R.1.1', 'K.story', 'Read: "Sam has a red hat. The hat is on a log. Sam gets the hat and puts it on." Where is the hat at first?', '["On a log","In a bag","On a bed"]', 0, 'The story says the hat is on a log. Then Sam gets it.', 10, 'mcq'),
('d4269ca7-bf1a-4582-aee5-8e8557c5d426', 'reading', 'K', 1, 'ELA.K.R.1.1', 'K.story', 'Read: "Sam has a red hat. The hat is on a log. Sam gets the hat and puts it on." What does Sam do at the end?', '["Gets a bag","Puts on the hat","Sits on a bed"]', 1, 'At the end, Sam gets the hat and puts it on.', 10, 'mcq'),
('079cfa4f-bbdc-493f-aba0-4100706c7fda', 'reading', 'K', 1, 'ELA.K.R.1.1', 'K.story', 'Read: "A cat sits on a mat. Pam sits by the cat. Pam pats the cat. The cat naps." Who sits by the cat?', '["Sam","A dog","Pam"]', 2, 'The story says Pam sits by the cat.', 10, 'mcq'),
('a6cd15f4-d8e8-4e80-a92c-b9af3c8f7a20', 'reading', 'K', 1, 'ELA.K.R.1.1', 'K.story', 'Read: "A cat sits on a mat. Pam sits by the cat. Pam pats the cat. The cat naps." What does the cat do last?', '["Naps","Runs","Jumps"]', 0, 'The last sentence tells us that the cat naps.', 10, 'mcq'),
('6b6321c7-5946-4072-acf0-70efbd0d8519', 'reading', '1', 1, 'ELA.1.R.1.1', '1.read', 'Read: "Nina made a bridge with blocks. Her toy bus was too wide to cross it. She moved the blocks apart and put a longer block on top. Now the bus could cross. Nina smiled and drove it over again." Why did Nina change her bridge?', '["The bus was too wide","The blocks were wet","The bus was missing"]', 0, 'Nina changes the bridge because her toy bus is too wide to cross it.', 10, 'mcq'),
('88056b29-b93d-4c1d-a264-7e460fd299d1', 'reading', '1', 1, 'ELA.1.R.1.1', '1.read', 'Read: "Nina made a bridge with blocks. Her toy bus was too wide to cross it. She moved the blocks apart and put a longer block on top. Now the bus could cross. Nina smiled and drove it over again." What happened after Nina changed the bridge?', '["She lost the bus","The bus could cross","The bridge got wet"]', 1, 'After she moves the blocks and adds a longer block, the bus can cross.', 10, 'mcq'),
('a1b8396b-7091-4923-a8b1-ae37095441c6', 'reading', '1', 1, 'ELA.1.R.1.1', '1.read', 'Read: "Leo and his dad packed a picnic. Rain began as they reached the door. Leo looked at the blanket in his bag. He spread it on the living room floor. They ate their lunch there and listened to the rain." Where do Leo and his dad eat their picnic?', '["At a park","On a bus","In the living room"]', 2, 'Leo spreads the blanket on the living room floor, and they eat there.', 10, 'mcq'),
('fdea6855-9124-4a3a-abfb-1c76682954d9', 'reading', '1', 1, 'ELA.1.R.1.1', '1.read', 'Read: "Leo and his dad packed a picnic. Rain began as they reached the door. Leo looked at the blanket in his bag. He spread it on the living room floor. They ate their lunch there and listened to the rain." Why do they have their picnic inside?', '["It starts to rain","They forget the food","The blanket is lost"]', 0, 'Rain begins when they reach the door. Leo finds a way to have the picnic inside.', 10, 'mcq'),
('ef1ffb89-85b4-4264-ac62-86e78ca93267', 'reading', '2', 2, 'ELA.2.R.1.3', '2.perspective', 'Read: "Mara wanted the biggest speaking part in the class play. Her friend Eli wanted to paint the scenery. Mara thought painting sounded dull until she watched Eli turn a plain sheet into a forest. Eli thought acting looked easy until he heard Mara practice her lines again and again. On show day, Mara thanked Eli for the forest, and Eli cheered when Mara spoke." How does Mara feel about painting scenery at first?', '["She thinks it sounds dull","She thinks it is the best job","She is afraid of it","She wants Eli to stop"]', 0, 'The passage says Mara thinks painting sounds dull at first, before she sees Eli make the forest.', 10, 'mcq'),
('b97595d3-7777-4d3d-a17f-abc90f0d71db', 'reading', '2', 2, 'ELA.2.R.1.3', '2.perspective', 'Read: "Mara wanted the biggest speaking part in the class play. Her friend Eli wanted to paint the scenery. Mara thought painting sounded dull until she watched Eli turn a plain sheet into a forest. Eli thought acting looked easy until he heard Mara practice her lines again and again. On show day, Mara thanked Eli for the forest, and Eli cheered when Mara spoke." What do Mara and Eli learn about each other’s jobs?', '["Only acting takes work","Both jobs take care and effort","Painting needs no practice","They should cancel the play"]', 1, 'Mara sees Eli transform a sheet. Eli hears Mara practice repeatedly. Each begins to appreciate the other’s work.', 10, 'mcq'),
('7bc909c8-68a2-4293-af2f-a4b18b57a835', 'reading', '2', 2, 'ELA.2.R.1.3', '2.perspective', 'Read: "Owen hurried along the trail because he wanted to reach the pond. His sister Rosa kept stopping to look at leaves and tiny tracks. Owen sighed each time she stopped. Then Rosa pointed out a line of ants carrying bits of a leaf. Owen crouched beside her. They reached the pond later than planned, but Owen had a new idea for his nature drawing." What matters most to Owen at the start?', '["Drawing ants","Finding a leaf","Reaching the pond","Going home"]', 2, 'Owen hurries because he wants to reach the pond. Rosa is interested in details along the way.', 10, 'mcq'),
('b76f7d50-93da-4261-ac89-7d1a039178a3', 'reading', '2', 2, 'ELA.2.R.1.3', '2.perspective', 'Read: "Owen hurried along the trail because he wanted to reach the pond. His sister Rosa kept stopping to look at leaves and tiny tracks. Owen sighed each time she stopped. Then Rosa pointed out a line of ants carrying bits of a leaf. Owen crouched beside her. They reached the pond later than planned, but Owen had a new idea for his nature drawing." How are Rosa and Owen different at first?', '["Both want to hurry","Rosa wants to leave the trail","Owen wants to stop more often","Rosa notices small things while Owen wants to keep moving"]', 3, 'Rosa stops for leaves and tracks. Owen hurries and sighs when she stops.', 10, 'mcq'),
('41c812c1-78a4-4337-aa2f-f15b18ad6d58', 'reading', '3', 2, 'ELA.3.R.1.3', '3.perspective', 'Read: "The school had one small courtyard. Ada proposed a quiet reading corner. Luis wanted space for a beanbag game. At first, each student thought the other idea would spoil the courtyard. Their teacher asked them to draw where their activities would happen. Ada placed her reading bench under the tree. Luis drew his game near the far wall. When they compared their plans, they noticed an empty path between the two spaces. Ada imagined reading while friends played nearby. Luis liked having somewhere to rest after a game. They submitted one plan together." Why do Ada and Luis disagree at first?', '["They want different uses for the same space","They cannot find the courtyard","Both want a reading bench under the tree","Neither wants to use the courtyard"]', 0, 'Ada wants a quiet reading corner, while Luis wants an active game space. Each worries that the other use will spoil the courtyard.', 10, 'mcq'),
('6232db9d-9ed1-4ceb-a5e6-b86a648884c7', 'reading', '3', 2, 'ELA.3.R.1.3', '3.perspective', 'Read: "The school had one small courtyard. Ada proposed a quiet reading corner. Luis wanted space for a beanbag game. At first, each student thought the other idea would spoil the courtyard. Their teacher asked them to draw where their activities would happen. Ada placed her reading bench under the tree. Luis drew his game near the far wall. When they compared their plans, they noticed an empty path between the two spaces. Ada imagined reading while friends played nearby. Luis liked having somewhere to rest after a game. They submitted one plan together." Which detail shows that their perspectives change?', '["The courtyard is small","They imagine enjoying parts of each other’s ideas","Their teacher asks them to draw","Luis draws near the far wall"]', 1, 'Ada imagines reading near the game, and Luis appreciates a resting place. They see value in each other’s ideas and submit one plan.', 10, 'mcq'),
('24713f7f-2902-4225-afd2-56d0a0e63e7d', 'reading', '3', 2, 'ELA.3.R.1.3', '3.perspective', 'Read: "Tess practiced her drum pattern after school. From her room, the steady beat sounded stronger every day. Across the hall, her brother Max was trying to record a poem for class. On his recording, the drum covered the last lines. Max knocked on Tess’s door and explained the problem. Tess had thought he disliked her music. When she heard the recording, she understood. They made a schedule: Max would record first, and then he would listen while Tess practiced her whole song." Why does Max ask Tess to stop drumming for a while?', '["He wants to play her drum","He dislikes every kind of music","The sound covers his poem recording","He wants to leave the house"]', 2, 'Max’s recording includes drum sounds that cover his last lines. His concern is recording the poem, not rejecting Tess’s music.', 10, 'mcq'),
('6033910c-5a11-4ee1-ad6b-4909dc040c9b', 'reading', '3', 2, 'ELA.3.R.1.3', '3.perspective', 'Read: "Tess practiced her drum pattern after school. From her room, the steady beat sounded stronger every day. Across the hall, her brother Max was trying to record a poem for class. On his recording, the drum covered the last lines. Max knocked on Tess’s door and explained the problem. Tess had thought he disliked her music. When she heard the recording, she understood. They made a schedule: Max would record first, and then he would listen while Tess practiced her whole song." What helps Tess understand Max’s perspective?', '["Learning a new drum pattern","Moving her drum across the room","Finishing her song","Listening to his recording"]', 3, 'When Tess hears the recording, she understands how her practice affects Max’s work.', 10, 'mcq'),
('9f582aa6-ae31-4a16-a462-7b22a793e6a3', 'reading', '4', 2, 'ELA.4.R.1.2', '4.theme', 'Read: "Jules arrived at the kite festival carrying a bright kite she had built alone. She had refused her cousin Mina’s offer to help because she wanted all the credit. At the field, the kite spun in circles and fell. Mina suggested making the tail longer, but Jules turned away. After the third crash, Jules studied the tangled string and finally asked Mina to show her idea. Together they added strips of cloth and tested the kite. It rose steadily. When a neighbor praised the design, Jules started to say that she had made it. Then she looked at Mina holding the spool and said they had improved it together." Which theme develops through Jules’s actions?', '["Accepting help can improve your work","Winning matters more than learning","Good ideas never need changes","Working alone always works best"]', 0, 'Jules first rejects help. After accepting Mina’s suggestion, the kite flies and Jules shares the credit. Those changes develop the theme.', 10, 'mcq'),
('7805294c-8fc6-4209-abea-b9802fc9bede', 'reading', '4', 2, 'ELA.4.R.1.2', '4.theme', 'Read: "Jules arrived at the kite festival carrying a bright kite she had built alone. She had refused her cousin Mina’s offer to help because she wanted all the credit. At the field, the kite spun in circles and fell. Mina suggested making the tail longer, but Jules turned away. After the third crash, Jules studied the tangled string and finally asked Mina to show her idea. Together they added strips of cloth and tested the kite. It rose steadily. When a neighbor praised the design, Jules started to say that she had made it. Then she looked at Mina holding the spool and said they had improved it together." Which detail best shows that Jules has learned this lesson?', '["She brings a bright kite to the festival","She gives Mina credit for improving the kite","The string gets tangled after a crash","A neighbor walks over to the kite"]', 1, 'Sharing credit shows more than a successful kite: Jules now values Mina’s contribution instead of wanting all the credit herself.', 10, 'mcq'),
('87531c76-faed-4d61-aa00-3366be5ea37a', 'reading', '4', 2, 'ELA.4.R.1.2', '4.theme', 'Read: "When the neighborhood announced a cleanup morning, Ravi promised to help repair the park bench. On Saturday, a friend invited him to try a new video game at the same time. Ravi nearly accepted. Then he remembered Mrs. Chen saying that she needed the bench to rest during her walks. He told his friend he would come later and went to the park. The repair took longer than he expected. Ravi sanded one rough board while an adult secured the loose parts. That afternoon, he saw Mrs. Chen sitting comfortably on the bench. He still wanted to play the game, but he was glad he had kept his promise." Which theme is supported by Ravi’s choice?', '["Games are never worth playing","Repairs should always be done alone","Keeping a promise can help others","Plans should never change for any reason"]', 2, 'Ravi chooses to honor his promise and later sees how the repaired bench helps Mrs. Chen. The story connects responsibility with helping another person.', 10, 'mcq'),
('fe235d3a-9d9d-4661-a3b2-660e503e3f8e', 'reading', '4', 2, 'ELA.4.R.1.2', '4.theme', 'Read: "When the neighborhood announced a cleanup morning, Ravi promised to help repair the park bench. On Saturday, a friend invited him to try a new video game at the same time. Ravi nearly accepted. Then he remembered Mrs. Chen saying that she needed the bench to rest during her walks. He told his friend he would come later and went to the park. The repair took longer than he expected. Ravi sanded one rough board while an adult secured the loose parts. That afternoon, he saw Mrs. Chen sitting comfortably on the bench. He still wanted to play the game, but he was glad he had kept his promise." How does the ending develop the theme?', '["It explains the rules of the game","It says the repair was easy","It shows Ravi forgetting his promise","It shows Ravi seeing the benefit of keeping his promise"]', 3, 'Seeing Mrs. Chen rest on the bench helps Ravi understand the value of the choice he made.', 10, 'mcq'),
('b9efee7d-1e28-4391-acdd-c422ae7ff17b', 'reading', '5', 2, 'ELA.5.R.1.3', '5.perspective', 'Read: "When the town planned a mural, Elena submitted a sketch of its newest buildings. She believed progress meant showing what was modern. At a planning meeting, an older resident described the small ferry that had once connected the town’s two shores. Elena had never noticed the faded ferry sign beside the bridge. She visited it the next day and found scratches where years of travelers had rested their bicycles. Back at her desk, she drew the ferry beneath a transparent outline of the current bridge. She kept the new buildings, too. When she presented the revision, she explained that a town’s future made more sense when people could also see how it had arrived there. The old sketch lay beside the new one, but she no longer wanted to use it." How does Elena’s perspective change?', '["She comes to value both the town’s history and its new development","She decides all new buildings should be removed","She thinks history has nothing to do with the mural","She loses interest in making a mural"]', 0, 'At first Elena includes only modern buildings. Her revised sketch combines the old ferry, the bridge, and new buildings, showing that she now values connections between past and present.', 10, 'mcq'),
('283a9509-39a3-4667-aea4-2e284545aa8c', 'reading', '5', 2, 'ELA.5.R.1.3', '5.perspective', 'Read: "When the town planned a mural, Elena submitted a sketch of its newest buildings. She believed progress meant showing what was modern. At a planning meeting, an older resident described the small ferry that had once connected the town’s two shores. Elena had never noticed the faded ferry sign beside the bridge. She visited it the next day and found scratches where years of travelers had rested their bicycles. Back at her desk, she drew the ferry beneath a transparent outline of the current bridge. She kept the new buildings, too. When she presented the revision, she explained that a town’s future made more sense when people could also see how it had arrived there. The old sketch lay beside the new one, but she no longer wanted to use it." How does the author develop this change?', '["By listing every building in town","By showing Elena listen, investigate, and revise her design","By saying all the residents agree with Elena","By describing only the colors of the mural"]', 1, 'The meeting introduces another viewpoint. Elena then visits the sign and changes her sketch. That sequence lets readers see her perspective develop through actions.', 10, 'mcq'),
('ede99d2e-7ac6-4f44-a285-45a60400d56a', 'reading', '5', 2, 'ELA.5.R.1.3', '5.perspective', 'Read: "Marcus was certain his team’s paper tower would hold the most coins. He had spent an evening folding its wide base and wanted to skip the final test. A teammate, Noor, asked to test a smaller model first. Marcus thought the test would waste their remaining time. During the trial, one folded seam bent and the model leaned. Marcus reached to straighten it, then stopped and asked Noor to note where the bend had started. They used a spare sheet to strengthen the matching seam on the full tower. Before the class demonstration, Marcus requested one more test himself. He still hoped their tower would do well, but now he wanted evidence that the design could support that hope." What change in Marcus’s perspective does the final sentence reveal?', '["He no longer cares about the project","He thinks Noor should work alone","He now values testing instead of relying only on confidence","He believes every test is a waste of time"]', 2, 'Marcus begins by wanting to skip testing. After the model bends, he asks for another test and wants evidence to support his confidence.', 10, 'mcq'),
('a7c991a5-f55c-4779-aafa-0e568065e07f', 'reading', '5', 2, 'ELA.5.R.1.3', '5.perspective', 'Read: "Marcus was certain his team’s paper tower would hold the most coins. He had spent an evening folding its wide base and wanted to skip the final test. A teammate, Noor, asked to test a smaller model first. Marcus thought the test would waste their remaining time. During the trial, one folded seam bent and the model leaned. Marcus reached to straighten it, then stopped and asked Noor to note where the bend had started. They used a spare sheet to strengthen the matching seam on the full tower. Before the class demonstration, Marcus requested one more test himself. He still hoped their tower would do well, but now he wanted evidence that the design could support that hope." Which action most clearly demonstrates his changed perspective?', '["Folding a wide base the night before","Hoping the tower holds many coins","Working with a teammate","Requesting another test before the demonstration"]', 3, 'His request reverses his earlier wish to skip the test. It directly shows that he has come to value evidence.', 10, 'mcq')
